import{_ as i,c as e,o as r,ag as l}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"常見問題","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/faq.md","filePath":"zh-TW/guide/faq.md","lastUpdated":1794112334000}'),t={name:"zh-TW/guide/faq.md"};function o(s,a,h,c,n,d){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><h2 id="一般問題" tabindex="-1">一般問題 <a class="header-anchor" href="#一般問題" aria-label="Permalink to &quot;一般問題&quot;">​</a></h2><h3 id="nicasa-是什麼" tabindex="-1">Nicasa 是什麼？ <a class="header-anchor" href="#nicasa-是什麼" aria-label="Permalink to &quot;Nicasa 是什麼？&quot;">​</a></h3><p>Nicasa 是一款專為 macOS 打造的現代桌面圖片檢視與截圖工具。它以乾淨、反應迅速的介面提供快速直觀的圖片瀏覽，並具備強大的 AI 編輯能力。</p><h3 id="nicasa-免費嗎" tabindex="-1">Nicasa 免費嗎？ <a class="header-anchor" href="#nicasa-免費嗎" aria-label="Permalink to &quot;Nicasa 免費嗎？&quot;">​</a></h3><p>Chrome 擴充功能完全免費，可隨意下載使用。macOS 應用程式需一次性支付 $4.99，才能解鎖全部功能。</p><h3 id="支援哪些作業系統" tabindex="-1">支援哪些作業系統？ <a class="header-anchor" href="#支援哪些作業系統" aria-label="Permalink to &quot;支援哪些作業系統？&quot;">​</a></h3><p>Nicasa 目前僅支援 macOS 10.13 或更高版本，暫不提供 Windows 與 Linux 版本。</p><h3 id="如何更新-nicasa" tabindex="-1">如何更新 Nicasa？ <a class="header-anchor" href="#如何更新-nicasa" aria-label="Permalink to &quot;如何更新 Nicasa？&quot;">​</a></h3><p>更新透過 Mac App Store 進行。有新版本時會收到通知，也可以直接在 App Store 應用程式中更新。</p><h2 id="使用問題" tabindex="-1">使用問題 <a class="header-anchor" href="#使用問題" aria-label="Permalink to &quot;使用問題&quot;">​</a></h2><h3 id="如何用-nicasa-截圖" tabindex="-1">如何用 Nicasa 截圖？ <a class="header-anchor" href="#如何用-nicasa-截圖" aria-label="Permalink to &quot;如何用 Nicasa 截圖？&quot;">​</a></h3><ol><li>啟動 Nicasa</li><li>點擊工具列中的截圖按鈕，或使用 <code>Cmd+S</code></li><li>選取你想要擷取的區域</li><li>截圖會在 Nicasa 中開啟，可立即編輯</li></ol><h3 id="nicasa-能處理網頁圖片嗎" tabindex="-1">Nicasa 能處理網頁圖片嗎？ <a class="header-anchor" href="#nicasa-能處理網頁圖片嗎" aria-label="Permalink to &quot;Nicasa 能處理網頁圖片嗎？&quot;">​</a></h3><p>可以！安裝免費的 Nicasa Chrome 擴充功能即可：</p><ul><li>在一個地方檢視任意網站的所有圖片</li><li>隨時擷取並瀏覽圖片</li><li>直接在 Nicasa 中開啟圖片，獲得更佳的檢視體驗</li></ul><h3 id="有哪些-ai-編輯功能" tabindex="-1">有哪些 AI 編輯功能？ <a class="header-anchor" href="#有哪些-ai-編輯功能" aria-label="Permalink to &quot;有哪些 AI 編輯功能？&quot;">​</a></h3><p>Nicasa 內建強大的 AI 工具：</p><ul><li><strong>自動增強</strong>：自動提升畫質</li><li><strong>智慧裁切</strong>：智慧裁切建議</li><li><strong>影像修復</strong>：智慧去除不需要的物體</li><li><strong>色彩校正</strong>：由 AI 驅動的色彩調整</li><li><strong>降噪</strong>：去除雜點與顆粒</li></ul><h3 id="透明懸浮模式是如何運作的" tabindex="-1">透明懸浮模式是如何運作的？ <a class="header-anchor" href="#透明懸浮模式是如何運作的" aria-label="Permalink to &quot;透明懸浮模式是如何運作的？&quot;">​</a></h3><p>為設計師與繪師量身打造：</p><ul><li>把圖片以可調透明度置頂於所有視窗之上</li><li>可用於描圖、參考對照或 UI 比對</li><li>在所有應用程式中保持位置不變</li></ul><h2 id="技術問題" tabindex="-1">技術問題 <a class="header-anchor" href="#技術問題" aria-label="Permalink to &quot;技術問題&quot;">​</a></h2><h3 id="為什麼需要授予螢幕錄製權限" tabindex="-1">為什麼需要授予螢幕錄製權限？ <a class="header-anchor" href="#為什麼需要授予螢幕錄製權限" aria-label="Permalink to &quot;為什麼需要授予螢幕錄製權限？&quot;">​</a></h3><p>截圖功能需要螢幕錄製權限，這樣 Nicasa 才能在你使用截圖工具時擷取螢幕。</p><h3 id="可以離線使用-nicasa-嗎" tabindex="-1">可以離線使用 Nicasa 嗎？ <a class="header-anchor" href="#可以離線使用-nicasa-嗎" aria-label="Permalink to &quot;可以離線使用 Nicasa 嗎？&quot;">​</a></h3><p>可以。macOS 應用程式可完全離線處理本機圖片檔案；透過 Chrome 擴充功能擷取網頁圖片則需要網路連線。</p><h3 id="支援哪些-macos-版本" tabindex="-1">支援哪些 macOS 版本？ <a class="header-anchor" href="#支援哪些-macos-版本" aria-label="Permalink to &quot;支援哪些 macOS 版本？&quot;">​</a></h3><p>Nicasa 支援 macOS 10.13 或更高版本，並針對 Apple 晶片最佳化，在 M 系列晶片上原生執行。</p><h3 id="chrome-擴充功能需要哪些權限" tabindex="-1">Chrome 擴充功能需要哪些權限？ <a class="header-anchor" href="#chrome-擴充功能需要哪些權限" aria-label="Permalink to &quot;Chrome 擴充功能需要哪些權限？&quot;">​</a></h3><p>該擴充功能僅為擷取圖片位址而請求讀取頁面內容，不會讀取或儲存瀏覽記錄。</p><h3 id="我的資料會被上傳嗎" tabindex="-1">我的資料會被上傳嗎？ <a class="header-anchor" href="#我的資料會被上傳嗎" aria-label="Permalink to &quot;我的資料會被上傳嗎？&quot;">​</a></h3><p>不會。所有處理都在你的裝置本機完成，Nicasa 不會蒐集、傳輸或儲存你的圖片。</p><h3 id="如何備份我的設定" tabindex="-1">如何備份我的設定？ <a class="header-anchor" href="#如何備份我的設定" aria-label="Permalink to &quot;如何備份我的設定？&quot;">​</a></h3><p>設定儲存在本機。備份方法：</p><ol><li>進入 Nicasa &gt; 偏好設定</li><li>如支援，匯出你的設定</li><li>或手動備份應用程式偏好設定檔案夾</li></ol><p>設定儲存在應用程式資料檔案夾中，複製該檔案夾即可完成備份。</p><h3 id="有可攜版嗎" tabindex="-1">有可攜版嗎？ <a class="header-anchor" href="#有可攜版嗎" aria-label="Permalink to &quot;有可攜版嗎？&quot;">​</a></h3><p>Windows 版本提供可攜版，可從我們的網站下載。</p><h2 id="開發問題" tabindex="-1">開發問題 <a class="header-anchor" href="#開發問題" aria-label="Permalink to &quot;開發問題&quot;">​</a></h2><h3 id="我可以為-nicasa-貢獻程式碼嗎" tabindex="-1">我可以為 Nicasa 貢獻程式碼嗎？ <a class="header-anchor" href="#我可以為-nicasa-貢獻程式碼嗎" aria-label="Permalink to &quot;我可以為 Nicasa 貢獻程式碼嗎？&quot;">​</a></h3><p>前往我們的 <a href="https://github.com/nicasa-project/nicasa-support" target="_blank" rel="noreferrer">GitHub 儲存庫</a>，貢獻程式碼、回報問題或提出功能建議。</p><h3 id="如何從原始碼建構-nicasa" tabindex="-1">如何從原始碼建構 Nicasa？ <a class="header-anchor" href="#如何從原始碼建構-nicasa" aria-label="Permalink to &quot;如何從原始碼建構 Nicasa？&quot;">​</a></h3><p>請參閱 GitHub 上的開發者文件以取得建構說明。</p><h3 id="nicasa-使用了哪些技術" tabindex="-1">Nicasa 使用了哪些技術？ <a class="header-anchor" href="#nicasa-使用了哪些技術" aria-label="Permalink to &quot;Nicasa 使用了哪些技術？&quot;">​</a></h3><p>Nicasa 使用現代 Web 技術建構，桌面端封裝使用 Electron，介面使用 Vue.js。</p><h2 id="隱私權問題" tabindex="-1">隱私權問題 <a class="header-anchor" href="#隱私權問題" aria-label="Permalink to &quot;隱私權問題&quot;">​</a></h2><h3 id="nicasa-會蒐集任何資料嗎" tabindex="-1">Nicasa 會蒐集任何資料嗎？ <a class="header-anchor" href="#nicasa-會蒐集任何資料嗎" aria-label="Permalink to &quot;Nicasa 會蒐集任何資料嗎？&quot;">​</a></h3><p>不會。Nicasa 不蒐集也不傳輸任何個人資料，所有圖片處理都在你的裝置本機完成。</p><h3 id="我的圖片安全嗎" tabindex="-1">我的圖片安全嗎？ <a class="header-anchor" href="#我的圖片安全嗎" aria-label="Permalink to &quot;我的圖片安全嗎？&quot;">​</a></h3><p>安全。Nicasa 只會存取你主動開啟的圖片，不會上傳或分享你的檔案。</p><h3 id="nicasa-需要哪些權限" tabindex="-1">Nicasa 需要哪些權限？ <a class="header-anchor" href="#nicasa-需要哪些權限" aria-label="Permalink to &quot;Nicasa 需要哪些權限？&quot;">​</a></h3><p>Nicasa 需要存取檔案系統以讀取圖片和儲存設定，執行時不依賴網路。</p><h2 id="還有疑問" tabindex="-1">還有疑問？ <a class="header-anchor" href="#還有疑問" aria-label="Permalink to &quot;還有疑問？&quot;">​</a></h2><p>如果在這裡找不到答案，請：</p><ol><li>查閱我們的<a href="/zh-TW/">完整文件</a></li><li>搜尋我們的 <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub issues</a></li><li>如有需要，新增一個 issue</li></ol><p>我們隨時為你提供協助！</p>',57)])])}const b=i(t,[["render",o]]);export{p as __pageData,b as default};
